-- =============================================================================
-- Tag logos live in the backend.
--
-- Until now 25 technology logos shipped as code (public/tag-icons/*.svg and a
-- map in lib/tag-icons.ts), as a fallback behind the kinds uploaded in
-- /admin/kinds. This moves them into tag_kinds so every logo is data:
--
--   mono     the logo is a black mark: the site draws it in the text colour,
--            so it stays visible in dark mode.
--   aliases  other spellings that show the same logo ("kdb" and "q" → kx).
--            Matched like names, through public.tag_key.
--
-- The built-in logos are inserted with their SVG inline as a data: URL, so
-- they need no storage upload. Replacing one in /admin/kinds uploads to the
-- media bucket as usual. A kind that already exists (Glyn's uploads) keeps
-- its icon; it only gains the aliases.
-- =============================================================================

alter table public.tag_kinds
  add column mono boolean not null default false,
  add column aliases text[] not null default '{}';

-- Same folding as tagKey() in lib/tag-icons.ts: "C++" → cplusplus,
-- "Next.js" → nextjs, "Tailwind CSS" → tailwindcss.
create or replace function public.tag_key(tag text)
returns text
language sql
immutable
set search_path = ''
as $$
  select regexp_replace(
    replace(replace(lower(tag), '+', 'plus'), '#', 'sharp'),
    '[^a-z0-9]', '', 'g'
  );
$$;

with built_in (name, icon_url, mono, aliases) as (
  values
  ('arduino', 'data:image/svg+xml;base64,', false, array[]::text[]),
  ('claude', 'data:image/svg+xml;base64,', false, array[]::text[]),
  ('cplusplus', 'data:image/svg+xml;base64,', false, array['cpp']::text[]),
  ('expo', 'data:image/svg+xml;base64,', true, array[]::text[]),
  ('kx', 'data:image/svg+xml;base64,', true, array['kdb', 'kdbplus', 'q']::text[]),
  ('matlab', 'data:image/svg+xml;base64,', false, array[]::text[]),
  ('modelcontextprotocol', 'data:image/svg+xml;base64,', true, array['mcp']::text[]),
  ('mdx', 'data:image/svg+xml;base64,', true, array[]::text[]),
  ('nextjs', 'data:image/svg+xml;base64,', true, array['next']::text[]),
  ('nvidia', 'data:image/svg+xml;base64,', false, array['nvidiajetson', 'jetson']::text[]),
  ('pixijs', 'data:image/svg+xml;base64,', false, array['pixi']::text[]),
  ('playwright', 'data:image/svg+xml;base64,', false, array[]::text[]),
  ('pwa', 'data:image/svg+xml;base64,', false, array[]::text[]),
  ('pyodide', 'data:image/svg+xml;base64,', false, array[]::text[]),
  ('python', 'data:image/svg+xml;base64,', false, array[]::text[]),
  ('react', 'data:image/svg+xml;base64,', false, array['reactnative']::text[]),
  ('ros', 'data:image/svg+xml;base64,', true, array[]::text[]),
  ('shadcnui', 'data:image/svg+xml;base64,', true, array['shadcn']::text[]),
  ('stripe', 'data:image/svg+xml;base64,', false, array[]::text[]),
  ('supabase', 'data:image/svg+xml;base64,', false, array[]::text[]),
  ('tailwindcss', 'data:image/svg+xml;base64,', false, array['tailwind']::text[]),
  ('typescript', 'data:image/svg+xml;base64,', false, array['ts']::text[]),
  ('unrealengine', 'data:image/svg+xml;base64,', true, array['unrealengine4', 'unrealengine5', 'ue4', 'ue5']::text[]),
  ('vercel', 'data:image/svg+xml;base64,PHN2ZyByb2xlPSJpbWciIHZpZXdCb3g9IjAgMCAyNCAyNCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48cGF0aCBkPSJtMTIgMS42MDggMTIgMjAuNzg0SDBaIi8+PC9zdmc+', true, array[]::text[]),
  ('yolo', 'data:image/svg+xml;base64,', true, array['yolov3', 'yolov5', 'yolov8']::text[])
),
existing as (
  update public.tag_kinds k
     set aliases = array(
       select distinct a from unnest(k.aliases || b.aliases) as a order by a
     )
    from built_in b
   where public.tag_key(k.name) = b.name
  returning public.tag_key(k.name) as key
)
insert into public.tag_kinds (name, icon_url, mono, aliases)
select b.name, b.icon_url, b.mono, b.aliases
  from built_in b
 where not exists (
   select 1 from public.tag_kinds k where public.tag_key(k.name) = b.name
 );
